from rest_framework_simplejwt.views import TokenRefreshView
from rest_framework_simplejwt.tokens import RefreshToken
from rest_framework.response import Response
from rest_framework import status
from .models import TenantMembership

class CustomTenantTokenRefreshView(TokenRefreshView):
    def post(self, request, *args, **kwargs):
        serializer = self.get_serializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        refresh_str = request.data.get("refresh")
        token = RefreshToken(refresh_str)
        user_id = token.payload.get("user_id")

        target_tenant = request.headers.get("X-Tenant-Context") or request.data.get("tenant_id")
        if target_tenant:
            if not TenantMembership.objects.filter(user_id=user_id, tenant_id=target_tenant, is_active=True).exists():
                return Response({"detail": "Unauthorized tenant context requested"}, status=status.HTTP_403_FORBIDDEN)
            token["tenant_id"] = str(target_tenant)

        return Response({
            "access": str(token.access_token),
            "refresh": str(token)
        }, status=status.HTTP_200_OK)
